  1	import { http, HttpResponse, type RequestHandler } from 'msw'
  2	import type { components } from '@/types/api.generated'
  3	
  4	type LoginResponse = components['schemas']['LoginResponse']
  5	type RegisterResponse = components['schemas']['RegisterResponse']
  6	
  7	const loginResponse = {
  8	  expiraEn: '2030-01-01T00:00:00Z',
  9	} satisfies LoginResponse
 10	
 11	const registerResponse = {
 12	  mensaje: 'Registration simulated.',
 13	  correo: 'demo.user@example.test',
 14	} satisfies RegisterResponse
 15	
 16	export const handlers: RequestHandler[] = [
 17	  http.post('/api/Auth/login', () =>
 18	    HttpResponse.json(loginResponse, { status: 200 }),
 19	  ),
 20	  http.post('/api/Auth/register', () =>
 21	    HttpResponse.json(registerResponse, { status: 200 }),
 22	  ),
 23	  http.post('/api/Concursos/crear', async ({ request }) => {
 24	    const formData = await request.formData()
 25	    const nombre = formData.get('nombre')
 26	    const codigo = formData.get('codigo')
 27	    if (typeof nombre !== 'string' || !nombre.trim())
 28	      return HttpResponse.json(
 29	        { mensaje: 'El nombre del concurso es obligatorio.' },
 30	        { status: 400 },
 31	      )
 32	    if (codigo === 'unauthorized')
 33	      return HttpResponse.json({ mensaje: 'Token inválido' }, { status: 401 })
 34	    return HttpResponse.json(
 35	      {
 36	        codigo: 'contest-demo',
 37	        mensaje: 'Concurso, problemas y casos de prueba creados exitosamente.',
 38	      },
 39	      { status: 200 },
 40	    )
 41	  }),
 42	]
