133	import React, { useState } from 'react';
134	import {Button,Card,Alert,Divider,} from '@/components/common';
135	import {FormField,Input,PasswordInput,} from '@/components/forms';
136	import type { LoginResponse } from '@/features/auth/authTypes';
137	import { authService } from '@/features/auth/authService';
138	
139	interface LoginFormProps {
140	  onToggleMode: () => void;
141	  onLoginSuccess: (res: LoginResponse) => void;
142	}
143	
144	export default function LoginForm({
145	  onToggleMode,
146	  onLoginSuccess,
147	}: LoginFormProps) {
148	  const [email, setEmail] = useState('');
149	  const [password, setPassword] = useState('');
150	  const [isLoading, setIsLoading] = useState(false);
151	
152	  const [errors, setErrors] = useState<{
153	    email?: string;
154	    password?: string;
155	    general?: string;
156	  }>({});
157	
158	  const handleSubmit = async (e: React.FormEvent) => {
159	    e.preventDefault();
160	    setErrors({});
161	
162	    const newErrors: typeof errors = {};
163	
164	    // Validaciones
165	    if (!email.trim()) {
166	      newErrors.email = 'El correo electrónico es requerido.';
167	    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
168	      newErrors.email = 'El correo electrónico no es válido.';
169	    }
170	
171	    if (!password) {
172	      newErrors.password = 'La contraseña es requerida.';
173	    }
174	
175	    if (Object.keys(newErrors).length > 0) {
176	      setErrors(newErrors);
177	      return;
178	    }
179	
180	    setIsLoading(true);
181	
182	    try {
183	      const authData = await authService.login({
184	        correo: email,
185	        contrasena: password,
186	      });
187	
188	      onLoginSuccess(authData);
189	
190	    } catch (error: any) {
191	      setErrors({
192	        general:
193	          error?.mensaje ||
194	          error?.error ||
195	          'No se pudo iniciar sesión.',
196	      });
197	    } finally {
198	      setIsLoading(false);
199	    }
200	  };
201	
202	  return (
203	    <div className='w-full max-w-md mx-auto px-4 py-8'>
204	      <Card className='space-y-8'>
205	
206	        {/* Header */}
207	        <div className='text-center space-y-2'>
208	          <h2 className='text-3xl font-bold tracking-tight text-[var(--text-primary)]'>
209	            Iniciar sesión
210	          </h2>
211	
212	          <p className='text-sm font-medium text-[var(--text-secondary)]'>
213	            Ingresa con tu cuenta para continuar
214	          </p>
215	        </div>
216	
217	        {/* Error global */}
218	        {errors.general && (
219	          <Alert tone='danger'>
220	            {errors.general}
221	          </Alert>
222	        )}
223	
224	        {/* Formulario */}
225	        <form onSubmit={handleSubmit} className='space-y-5'>
226	
227	          <FormField
228	            label='Correo electrónico'
229	            error={errors.email}
230	          >
231	            <Input
232	              type='email'
233	              placeholder='ejemplo@upds.edu.bo'
234	              value={email}
235	              onChange={(e) => setEmail(e.target.value)}
236	              disabled={isLoading}
237	            />
238	          </FormField>
239	
240	          <FormField
241	            label='Contraseña'
242	            error={errors.password}
243	          >
244	            <PasswordInput
245	              placeholder='••••••••'
246	              value={password}
247	              onChange={(e) => setPassword(e.target.value)}
248	              disabled={isLoading}
249	            />
250	          </FormField>
251	
252	          {/* Recuperar contraseña */}
253	          <div className='flex justify-end'>
254	            <button
255	              type='button'
256	              className='text-sm font-semibold text-[var(--primary)] hover:underline'
257	            >
258	              ¿Olvidaste tu contraseña?
259	            </button>
260	          </div>
261	
262	          {/* Botón principal */}
263	          <Button
264	            type='submit'
265	            fullWidth
266	            loading={isLoading}
267	          >
268	            Iniciar sesión
269	          </Button>
270	        </form>
271	
272	        {/* Divider */}
273	        <div className='relative'>
274	          <Divider />
275	
276	          <div className='absolute inset-0 flex items-center justify-center'>
277	            <span className='bg-[var(--surface)] px-3 text-xs font-semibold uppercase tracking-wider text-[var(--text-secondary)]'>
278	              o
279	            </span>
280	          </div>
281	        </div>
282	
283	        {/* Link a register */}
284	        <div className='text-center text-sm font-medium text-[var(--text-secondary)]'>
285	          ¿Aún no tienes una cuenta?{' '}
286	
287	          <button
288	            type='button'
289	            onClick={onToggleMode}
290	            className='font-semibold text-[var(--primary)] hover:underline'
291	          >
292	            Crear cuenta
293	          </button>
294	        </div>
295	
296	      </Card>
297	
298	      {/* Footer */}
299	      <div className='mt-8 flex items-center justify-center gap-4 text-xs font-medium text-[var(--text-secondary)]'>
300	        <a
301	          href='#terms'
302	          className='hover:text-[var(--text-primary)] transition-colors'
303	        >
304	          Términos de uso
305	        </a>
306	
307	        <a
308	          href='#privacy'
309	          className='hover:text-[var(--text-primary)] transition-colors'
310	        >
311	          Política de privacidad
312	        </a>
313	      </div>
314	    </div>
315	  );
316	}
317	import React, { useState } from 'react';
318	import {Button,Card,Alert,} from '@/components/common';
319	import {FormField,Input,PasswordInput,Checkbox,PasswordStrength,} from '@/components/forms';
320	import { CheckCircle2 } from 'lucide-react';
321	import { authService } from '@/features/auth/authService';
322	
323	interface RegisterFormProps {
324	  onToggleMode: () => void;
325	}
326	
327	export default function RegisterForm({
328	  onToggleMode,
329	}: RegisterFormProps) {
330	  const [name, setName] = useState('');
331	  const [email, setEmail] = useState('');
332	  const [password, setPassword] = useState('');
333	  const [confirmPassword, setConfirmPassword] = useState('');
334	  const [acceptTerms, setAcceptTerms] = useState(false);
335	
336	  const [isLoading, setIsLoading] = useState(false);
337	  const [showSuccessAlert, setShowSuccessAlert] = useState(false);
338	
339	  const [errors, setErrors] = useState<{
340	    name?: string;
341	    email?: string;
342	    password?: string;
343	    confirmPassword?: string;
344	    general?: string;
345	  }>({});
346	
347	  const handleSubmit = async (e: React.FormEvent) => {
348	    e.preventDefault();
349	    setErrors({});
350	
351	    const newErrors: typeof errors = {};
352	
353	    // Validaciones
354	    if (!name.trim()) {
355	      newErrors.name = 'El nombre completo es requerido.';
356	    }
357	
358	    if (!email.trim()) {
359	    newErrors.email = 'El correo electrónico es requerido.';
360	    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
361	      newErrors.email = 'El correo electrónico no es válido.';
362	    }
363	
364	    if (!password) {
365	    newErrors.password = 'La contraseña es requerida.';
366	    } else if (!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/.test(password)) {
367	    newErrors.password =
368	      'La contraseña debe tener al menos 8 caracteres, una letra mayúscula, una letra minúscula y un número.';
369	    }
370	
371	    if (!confirmPassword) {
372	      newErrors.confirmPassword = 'Debes confirmar la contraseña.';
373	    } else if (password !== confirmPassword) {
374	      newErrors.confirmPassword = 'Las contraseñas no coinciden.';
375	    }
376	
377	    if (!acceptTerms) {
378	      newErrors.general =
379	        'Debes aceptar los términos y condiciones.';
380	    }
381	
382	    if (Object.keys(newErrors).length > 0) {
383	      setErrors(newErrors);
384	      return;
385	    }
386	
387	    setIsLoading(true);
388	
389	    try {
390	      await authService.register({
391	        nombre: name,
392	        correo: email,
393	        contrasena: password,
394	      });
395	
396	      setShowSuccessAlert(true);
397	
398	      // Redirigir al login después de 2.5 segundos
399	      setTimeout(() => {
400	        onToggleMode();
401	      }, 2500);
402	
403	    } catch (error: any) {
404	      setErrors({
405	        general:
406	          error?.mensaje ||
407	          error?.error ||
408	          'No se pudo crear la cuenta.',
409	      });
410	    } finally {
411	      setIsLoading(false);
412	    }
413	  };
414	
415	  return (
416	    <div className='w-full max-w-md mx-auto px-4 py-8'>
417	      <Card className='space-y-6'>
418	
419	        {/* Éxito */}
420	        {showSuccessAlert && (
421	          <Alert tone='success' className='flex items-start gap-3'>
422	            <CheckCircle2 className='size-5 shrink-0 mt-0.5' />
423	
424	            <div className='text-left'>
425	              <p className='font-semibold'>
426	                ¡Cuenta creada con éxito!
427	              </p>
428	
429	              <p className='mt-1 text-sm'>
430	                Ya puedes iniciar sesión.
431	              </p>
432	            </div>
433	          </Alert>
434	        )}
435	
436	        {/* Header */}
437	        <div className='text-center space-y-2'>
438	          <h2 className='text-3xl font-bold tracking-tight text-[var(--text-primary)]'>
439	            Crear una cuenta
440	          </h2>
441	
442	          <p className='text-sm font-medium text-[var(--text-secondary)]'>
443	            Completa tus datos para comenzar.
444	          </p>
445	        </div>
446	
447	        {/* Error global */}
448	        {errors.general && !showSuccessAlert && (
449	          <Alert tone='danger'>
450	            {errors.general}
451	          </Alert>
452	        )}
453	
454	        {/* Formulario */}
455	        <form onSubmit={handleSubmit} className='space-y-5'>
456	
457	          <FormField
458	            label='Nombre completo'
459	            error={errors.name}
460	          >
461	            <Input
462	              type='text'
463	              placeholder='Ej. Juan Pérez'
464	              value={name}
465	              onChange={(e) => setName(e.target.value)}
466	              disabled={isLoading || showSuccessAlert}
467	            />
468	          </FormField>
469	
470	          <FormField
471	            label='Correo electrónico'
472	            error={errors.email}
473	          >
474	            <Input
475	              type='email'
476	              placeholder='juan.perez@upds.edu.bo'
477	              value={email}
478	              onChange={(e) => setEmail(e.target.value)}
479	              disabled={isLoading || showSuccessAlert}
480	            />
481	          </FormField>
482	
483	          {/* Contraseña */}
484	          <div className='space-y-2'>
485	            <FormField
486	              label='Contraseña'
487	              error={errors.password}
488	            >
489	              <PasswordInput
490	                placeholder='Crea tu contraseña'
491	                value={password}
492	                onChange={(e) => setPassword(e.target.value)}
493	                disabled={isLoading || showSuccessAlert}
494	              />
495	            </FormField>
496	
497	            {password && (
498	              <div className='space-y-2'>
499	                <PasswordStrength value={password} />
500	
501	                <p className="text-xs text-[var(--text-secondary)]">
502	                  Usa al menos 8 caracteres, una letra mayúscula, una letra
503	                  minúscula y un número.
504	                </p>
505	              </div>
506	            )}
507	          </div>
508	
509	          {/* Confirmar contraseña */}
510	          <FormField
511	            label='Confirmar contraseña'
512	            error={errors.confirmPassword}
513	          >
514	            <PasswordInput
515	              placeholder='Confirma tu contraseña'
516	              value={confirmPassword}
517	              onChange={(e) => setConfirmPassword(e.target.value)}
518	              disabled={isLoading || showSuccessAlert}
519	            />
520	          </FormField>
521	
522	          {/* Términos */}
523	          <label className='flex items-start gap-3 text-sm text-[var(--text-secondary)]'>
524	            <Checkbox
525	              checked={acceptTerms}
526	              onChange={(e) => setAcceptTerms(e.target.checked)}
527	              disabled={isLoading || showSuccessAlert}
528	            />
529	
530	            <span>
531	              Acepto los términos de uso y la política de privacidad.
532	            </span>
533	          </label>
534	
535	          {/* Botón */}
536	          <Button
537	            type='submit'
538	            fullWidth
539	            loading={isLoading || showSuccessAlert}
540	          >
541	            {isLoading || showSuccessAlert
542	              ? 'Creando cuenta...'
543	              : 'Crear cuenta'}
544	          </Button>
545	        </form>
546	
547	        {/* Link a login */}
548	        <div className='text-center text-sm font-medium text-[var(--text-secondary)]'>
549	          ¿Ya tienes una cuenta?{' '}
550	
551	          <button
552	            type='button'
553	            onClick={onToggleMode}
554	            className='font-semibold text-[var(--primary)] hover:underline'
555	          >
556	            Iniciar sesión
557	          </button>
558	        </div>
559	
560	      </Card>
561	    </div>
562	  );
563	}
564	import { useNavigate } from 'react-router-dom';
565	import AuthTemplate from '@/features/auth/templates/AuthTemplate';
566	import LoginForm from '@/features/auth/Components/LoginForm';
567	import type { LoginResponse } from '@/features/auth/authTypes';
568	
569	export default function LoginPage() {
570	  const navigate = useNavigate();
571	
572	  const handleLoginSuccess = (res: LoginResponse) => {
573	    // Guardar JWT
574	    sessionStorage.setItem('token', res.token);
575	
576	    // Ir al dashboard
577	    navigate('/dashboard');
578	  };
579	
580	  return (
581	    <AuthTemplate mode="login">
582	      <LoginForm
583	        onToggleMode={() => navigate('/register')}
584	        onLoginSuccess={handleLoginSuccess}
585	      />
586	    </AuthTemplate>
587	  );
588	}
589	import { useNavigate } from 'react-router-dom';
590	import AuthTemplate from '@/features/auth/templates/AuthTemplate';
591	import RegisterForm from '@/features/auth/Components/RegisterForm';
592	
593	export default function RegisterPage() {
594	  const navigate = useNavigate();
595	
596	  return (
597	    <AuthTemplate mode='register'>
598	      <RegisterForm
599	        onToggleMode={() => navigate('/login')}
600	      />
601	    </AuthTemplate>
602	  );
603	}
604	import { useNavigate } from 'react-router-dom';
605	import { Button, Card } from '@/components/common';
606	
607	export default function DashboardPage() {
608	  const navigate = useNavigate();
609	
610	  const handleLogout = () => {
611	    // Borrar el JWT
612	    sessionStorage.removeItem('token');
613	
614	    // Volver al login
615	    navigate('/login');
616	  };
617	
618	  return (
619	    <div className="min-h-screen flex items-center justify-center bg-[var(--background)] p-6">
620	      <Card className="max-w-md w-full text-center space-y-6">
621	        <h1 className="text-3xl font-bold text-[var(--text-primary)]">
622	          ¡Bienvenido a UPDS Judge!
623	        </h1>
624	
625	        <p className="text-[var(--text-secondary)]">
626	          Has iniciado sesión correctamente y tu ruta está protegida mediante JWT.
627	        </p>
628	
629	        <Button
630	          variant="outline"
631	          fullWidth
632	          onClick={handleLogout}
633	        >
634	          Cerrar sesión
635	        </Button>
636	      </Card>
637	    </div>
638	  );
639	}

